practice.solution:
def npub_ok(s):
    if not s.startswith('npub1'):
        return False
    if len(s) != 63:
        return False
    chars = 'qpzry9x8gf2tvdw0s3jn54khce6mua7l'
    for ch in s[5:]:
        if ch not in chars:
            return False
    return True

