practice.starter:
def parse_roll(text):
    # your code
    pass

practice.solution:
def parse_roll(text):
    if not text.startswith('/roll '):
        return [0, 0]
    body = text[6:]
    if 'd' not in body:
        return [0, 0]
    a, b = body.split('d', 1)
    if a == '' or b == '':
        return [0, 0]
    for ch in a + b:
        if ch not in '0123456789':
            return [0, 0]
    n = int(a)
    s = int(b)
    if n < 1 or s < 1:
        return [0, 0]
    return [n, s]

