practice.starter:
def storm(times, window, limit):
    # your code
    pass

practice.solution:
def storm(times, window, limit):
    for i in range(len(times)):
        c = 0
        for t in times:
            if t >= times[i] and t < times[i] + window:
                c += 1
        if c > limit:
            return True
    return False
